  "lvl.after3": ["sau 3 việc khởi đầu", "after 3 starter tasks", "หลังทำ 3 งานเริ่มต้น", "完成 3 项新手任务后", "tras 3 tareas iniciales", "após 3 tarefas iniciais"],
  "lvl.howEarn": ["Cách kiếm xu tím", "How to earn purple coins", "วิธีรับเหรียญม่วง", "如何获得紫币", "Cómo ganar monedas moradas", "Como ganhar moedas roxas"],
  "lvl.e1": ["Gửi tin nhắn trong nhóm", "Send a message in a group", "ส่งข้อความในกลุ่ม", "在群组中发消息", "Enviar un mensaje en un grupo", "Enviar uma mensagem num grupo"],
  "lvl.e1n": ["Tin từ 5 ký tự, không trùng tin liền trước, không tính tin nhắn riêng", "Messages of 5+ characters, not repeating your previous message; direct messages do not count", "ข้อความตั้งแต่ 5 ตัวอักษร ไม่ซ้ำกับข้อความก่อนหน้า ไม่นับข้อความส่วนตัว", "5 个字符以上，不与上一条重复，私信不计", "Mensajes de 5+ caracteres, sin repetir el anterior; los mensajes directos no cuentan", "Mensagens com 5+ caracteres, sem repetir a anterior; mensagens diretas não contam"],
  "lvl.e2": ["Tin của bạn được thả tim", "Your message gets a like", "ข้อความของคุณได้รับหัวใจ", "你的消息被点赞", "Tu mensaje recibe un me gusta", "Sua mensagem recebe uma curtida"],
