  "lvl.welcomeCap": ["CHÀO MỪNG BẠN", "WELCOME", "ยินดีต้อนรับ", "欢迎你", "TE DAMOS LA BIENVENIDA", "BOAS-VINDAS"],
  "lvl.congratsCap": ["CHÚC MỪNG BẠN ĐÃ LÊN CẤP", "CONGRATS, YOU LEVELED UP", "ยินดีด้วย คุณเลื่อนระดับแล้ว", "恭喜你升级了", "FELICIDADES, SUBISTE DE NIVEL", "PARABÉNS, VOCÊ SUBIU DE NÍVEL"],
  "lvl.firstDone": ["Bạn đã xong các việc khởi đầu. Xu tím bạn đã kiếm từ trước vẫn được giữ nguyên.", "You finished the starter tasks. Purple coins you already earned are kept.", "คุณทำงานเริ่มต้นครบแล้ว เหรียญม่วงที่ได้มาก่อนหน้ายังอยู่ครบ", "你已完成新手任务。之前获得的紫币会保留。", "Completaste las tareas iniciales. Conservas las monedas moradas que ya ganaste.", "Você concluiu as tarefas iniciais. As moedas roxas que você já ganhou são mantidas."],
  "lvl.reachedCoins": ["Bạn đạt {n} xu tím. Cảm ơn bạn đã gắn bó với cộng đồng.", "You reached {n} purple coins. Thank you for being part of the community.", "คุณมีเหรียญม่วงครบ {n} แล้ว ขอบคุณที่อยู่กับชุมชนของเรา", "你已获得 {n} 紫币。感谢你一直陪伴社区。", "Llegaste a {n} monedas moradas. Gracias por formar parte de la comunidad.", "Você chegou a {n} moedas roxas. Obrigado por fazer parte da comunidade."],
