  "wl.none": ["Chưa có lời chào", "No welcomes yet", "ยังไม่มีคำทักทาย", "还没有欢迎语", "Aún sin bienvenidas", "Ainda sem boas-vindas"],
  "wl.backGroup": ["Quay lại nhóm", "Back to group", "กลับไปที่กลุ่ม", "返回群组", "Volver al grupo", "Voltar ao grupo"],
  "wl.intro": ["Thành viên tham gia trong {d} ngày qua. Lời chào ở đây gửi riêng cho từng người và không hiện trong khung chat chung của nhóm. Mỗi người được chào tối đa {n} lần bởi cùng một bạn.", "Members who joined in the last {d} days. Welcomes here go to each person privately and do not appear in the group chat. You can welcome each person up to {n} times.", "สมาชิกที่เข้าร่วมใน {d} วันที่ผ่านมา คำทักทายที่นี่ส่งถึงแต่ละคนเป็นการส่วนตัวและไม่แสดงในแชทกลุ่ม คุณทักทายแต่ละคนได้สูงสุด {n} ครั้ง", "过去 {d} 天内加入的成员。这里的欢迎语单独发给每个人，不会出现在群聊中。你最多可以欢迎每人 {n} 次。", "Miembros que se unieron en los últimos {d} días. Las bienvenidas llegan a cada persona en privado y no aparecen en el chat del grupo. Puedes saludar a cada persona hasta {n} veces.", "Membros que entraram nos últimos {d} dias. As boas-vindas vão para cada pessoa em particular e não aparecem no chat do grupo. Você pode dar boas-vindas a cada pessoa até {n} vezes."],
  "wl.noNew": ["Chưa có thành viên mới trong thời gian gần đây.", "No new members recently.", "ช่วงนี้ยังไม่มีสมาชิกใหม่", "最近没有新成员。", "No hay miembros nuevos recientemente.", "Nenhum membro novo recentemente."],
  "wl.sent": ["Đã gửi lời chào 💜", "Welcome sent 💜", "ส่งคำทักทายแล้ว 💜", "欢迎语已发送 💜", "Bienvenida enviada 💜", "Boas-vindas enviadas 💜"],
  // ---- games.js, bugs.js ----
  "gm.mtDesc": ["Cược xu tím vào võ sĩ, hoặc mời bạn bè thách đấu 1v1 có cược. Cược từ 10 đến 500 xu, thắng nhận x1.9.", "Bet purple coins on a fighter, or challenge a friend to a 1v1 match with a bet. Bets from 10 to 500 coins; winners get x1.9.", "เดิมพันเหรียญม่วงกับนักมวย หรือท้าเพื่อนดวล 1v1 แบบมีเดิมพัน เดิมพัน 10 ถึง 500 เหรียญ ชนะได้ x1.9", "用紫币押注拳手，或邀请好友进行有押注的 1v1 对决。押注 10 到 500 紫币，赢了得 1.9 倍。", "Apuesta monedas moradas a un luchador o reta a un amigo a un 1v1 con apuesta. Apuestas de 10 a 500 monedas; quien gana recibe x1,9.", "Aposte moedas roxas num lutador ou desafie um amigo para um 1v1 com aposta. Apostas de 10 a 500 moedas; quem vence recebe x1,9."],
  "gm.pets": ["Nuôi thú", "Pets", "เลี้ยงสัตว์", "养宠物", "Mascotas", "Bichinhos"],
  "gm.petsDesc": ["Nuôi Juad, Abu, Uni, Charsiu, Tofu và Udon trong khu nhà của bạn. Chăm sóc miễn phí, tăng Thân thiết, mở rộng khu nhà bằng xu tím.", "Raise Juad, Abu, Uni, Charsiu, Tofu and Udon in your home area. Care is free; build friendship and expand your home with purple coins.", "เลี้ยง Juad, Abu, Uni, Charsiu, Tofu และ Udon ในบ้านของคุณ ดูแลฟรี เพิ่มความสนิท และขยายบ้านด้วยเหรียญม่วง", "在你的家园里养 Juad、Abu、Uni、Charsiu、Tofu 和 Udon。照顾免费，提升亲密度，用紫币扩建家园。", "Cría a Juad, Abu, Uni, Charsiu, Tofu y Udon en tu casa. Cuidarlos es gratis; gana cercanía y amplía tu casa con monedas moradas.", "Cuide de Juad, Abu, Uni, Charsiu, Tofu e Udon na sua casa. Cuidar é grátis; aumente a amizade e amplie a casa com moedas roxas."],
  "gm.intro": ["Chơi bằng xu tím. Thắng thua được cộng trừ vào “Xu có thể tiêu” và không làm đổi cấp bậc của bạn.", "Play with purple coins. Wins and losses change your \"Coins to spend\" and never change your level.", "เล่นด้วยเหรียญม่วง ผลแพ้ชนะจะบวกหรือลบใน \"เหรียญที่ใช้ได้\" และไม่เปลี่ยนระดับของคุณ", "用紫币游玩。输赢只计入“可用紫币”，不会改变你的等级。", "Juega con monedas moradas. Lo que ganas o pierdes cambia tus \"Monedas para gastar\" y nunca tu nivel.", "Jogue com moedas roxas. Ganhos e perdas mudam suas \"Moedas para gastar\" e nunca o seu nível."],
  "gm.playN": ["Chơi {n}", "Play {n}", "เล่น {n}", "玩 {n}", "Jugar {n}", "Jogar {n}"],
  "gm.beta": ["Thử nghiệm", "Beta", "ทดลอง", "测试", "Beta", "Beta"],
  "gm.challenges": ["{n} lời thách đấu đang chờ", "{n} challenges waiting", "คำท้าที่รออยู่ {n} รายการ", "{n} 个挑战待回复", "{n} retos en espera", "{n} desafios aguardando"],
  "gm.play": ["Chơi", "Play", "เล่น", "开始", "Jugar", "Jogar"],
  "gm.more": ["Sẽ có thêm game ở đây.", "More games coming soon.", "เร็ว ๆ นี้จะมีเกมเพิ่ม", "更多游戏即将推出。", "Pronto habrá más juegos.", "Mais jogos em breve."],
  "bg.intro": ["Mô tả lỗi bạn gặp. Chúng tôi tự đính kèm trang bạn đang mở và loại thiết bị để dễ tìm lỗi.", "Describe the problem. We automatically attach the page you are on and your device type to help find it.", "อธิบายปัญหาที่พบ เราจะแนบหน้าที่คุณเปิดอยู่และประเภทอุปกรณ์ให้อัตโนมัติเพื่อช่วยค้นหา", "请描述你遇到的问题。我们会自动附上你当前的页面和设备类型，方便排查。", "Describe el problema. Adjuntamos automáticamente la página en la que estás y tu tipo de dispositivo.", "Descreva o problema. Anexamos automaticamente a página em que você está e o tipo de aparelho."],
  "bg.titlePh": ["Ví dụ: Không gửi được ảnh", "e.g. Cannot send photos", "เช่น ส่งรูปไม่ได้", "例如：无法发送图片", "p. ej.: No puedo enviar fotos", "ex.: Não consigo enviar fotos"],
  "bg.what": ["Chuyện gì đã xảy ra?", "What happened?", "เกิดอะไรขึ้น?", "发生了什么？", "¿Qué pasó?", "O que aconteceu?"],
  "bg.whatPh": ["Bạn đã làm gì, mong đợi gì, và thực tế ra sao?", "What did you do, what did you expect, and what actually happened?", "คุณทำอะไร คาดหวังอะไร และเกิดอะไรขึ้นจริง?", "你做了什么、期望什么、实际发生了什么？", "¿Qué hiciste, qué esperabas y qué pasó en realidad?", "O que você fez, o que esperava e o que aconteceu de fato?"],
  "bg.shot": ["Ảnh chụp màn hình (không bắt buộc, tối đa 2MB)", "Screenshot (optional, max 2MB)", "ภาพหน้าจอ (ไม่บังคับ สูงสุด 2MB)", "截图（可选，最大 2MB）", "Captura de pantalla (opcional, máx. 2 MB)", "Captura de tela (opcional, máx. 2 MB)"],
  "bg.send": ["Gửi báo lỗi", "Send report", "ส่งรายงานปัญหา", "提交反馈", "Enviar reporte", "Enviar relato"],
  "bg.sent": ["Đã gửi báo lỗi. Cảm ơn bạn!", "Bug report sent. Thank you!", "ส่งรายงานปัญหาแล้ว ขอบคุณ!", "问题反馈已提交，谢谢！", "Reporte enviado. ¡Gracias!", "Relato enviado. Obrigado!"],
